(function () {
    const MAX_ATTEMPTS = 20; // 20 attempts over 100 seconds
    const RETRY_INTERVAL = 5000; // 5 seconds
    let attempts = 0;
    let intervalId;

    // Check if already navigated
    if (sessionStorage.getItem("ig_profile_navigated") === "true") {
        return;
    }



    const verifyProfile = async () => {
        try {
            // using this instead of the dom to get the username (since it can be spoofed with script)
            const csrfCookie = document.cookie.split('; ').find(row => row.startsWith('csrftoken='));
            const csrftoken = csrfCookie ? csrfCookie.split('=')[1] : '';

            // Get user data
            const userResponse = await fetch('https://www.instagram.com/api/v1/accounts/edit/web_form_data/', {
                credentials: 'include',
                headers: {
                    'X-CSRFToken': csrftoken,
                    'X-IG-App-ID': '936619743392459',
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });

            const userData = await userResponse.json();
            const username = userData.form_data?.username;



            // Method 1: Use Instagram's web API endpoint
            const response = await fetch(`https://www.instagram.com/api/v1/users/web_profile_info/?username=${username}`, {
                method: 'GET',
                headers: {
                    'X-IG-App-ID': '936619743392459',
                    'X-Requested-With': 'XMLHttpRequest',
                },
                credentials: 'include',
            });

            if (!response.ok) {
                throw new Error(`API request failed with status: ${response.status}`);
            }

            const data = await response.json();
            const user = data?.data?.user;

            if (user) {
                const profileData = {
                    username: user.username,
                    fullName: user.full_name,
                    biography: user.biography,
                    profilePicUrl: user.profile_pic_url,
                    profilePicUrlHD: user.profile_pic_url_hd,
                    followersCount: user.edge_followed_by?.count,
                    followingCount: user.edge_follow?.count,
                    postsCount: user.edge_owner_to_timeline_media?.count,
                    isPrivate: user.is_private,
                    isVerified: user.is_verified,
                    externalUrl: user.external_url,
                    id: user.id,
                };


                const rd = {
                    url: `https://www.instagram.com/api/v1/users/web_profile_info/?username=${username}`,
                    headers: {
                        "accept-language": "en-US,en;q=0.9",
                        "priority": "u=1, i",
                        "sec-ch-prefers-color-scheme": "dark",
                        "sec-ch-ua": "\"Google Chrome\";v=\"143\", \"Chromium\";v=\"143\", \"Not A(Brand\";v=\"24\"",
                        "sec-ch-ua-full-version-list": "\"Google Chrome\";v=\"143.0.7499.111\", \"Chromium\";v=\"143.0.7499.111\", \"Not A(Brand\";v=\"24.0.0.0\"",
                        "sec-ch-ua-mobile": "?0",
                        "sec-ch-ua-model": "\"\"",
                        "sec-ch-ua-platform": "\"macOS\"",
                        "sec-ch-ua-platform-version": "\"26.2.0\"",
                        "sec-fetch-dest": "empty",
                        "sec-fetch-mode": "cors",
                        "sec-fetch-site": "same-origin",
                        "x-ig-app-id": "936619743392459",
                        "x-requested-with": "XMLHttpRequest"
                    },
                    method: 'GET',
                    requestBody: '',
                    responseBody: 'response',
                    extractedParams: {
                        username: profileData.username,
                        follower_count: profileData.followersCount.toString(),
                        is_verified: profileData.isVerified.toString()
                    },
                    responseMatches: [
                        {
                            type: 'contains',
                            value: "{{username}}"
                        },
                        {
                            type: 'contains',
                            value: "{{follower_count}}"
                        },
                        {
                            type: 'contains',
                            value: "{{is_verified}}"
                        }
                    ],
                    responseRedactions: [
                        {
                            regex: "{{username}}"
                        },
                        {
                            regex: "{{follower_count}}"
                        },
                        {
                            regex: "{{is_verified}}"
                        }
                    ],
                }

                window.Reclaim.requestClaim(rd);


                // Store in sessionStorage for later use
                sessionStorage.setItem('ig_profile_data', JSON.stringify(profileData));

                // Dispatch custom event with profile data
                window.dispatchEvent(new CustomEvent('ig_profile_data_loaded', {
                    detail: profileData
                }));

                return profileData;
            }
        } catch (error) {
            console.error('Error fetching profile data:', error);
        }
    };





    const getUsername = () => {
        try {
            // Method 1: Extract from HTML content using regex
            const htmlContent = document.documentElement.innerHTML;
            const regex = /"username"\s*:\s*"([^"]+)"/g;

            let match;
            const usernames = [];

            // Find all username matches
            while ((match = regex.exec(htmlContent)) !== null) {
                usernames.push(match[1]);
            }

            // Filter out common non-user usernames and get the most common one
            const filteredUsernames = usernames.filter(u =>
                u &&
                u.length > 0 &&
                !u.includes('instagram') &&
                !u.includes('null')
            );

            if (filteredUsernames.length > 0) {
                // Return the first valid username found
                return filteredUsernames[0];
            }

            // Method 2: From _sharedData (backup)
            if (window._sharedData?.config?.viewer?.username) {
                return window._sharedData.config.viewer.username;
            }

            // Method 3: From __additionalDataLoaded (backup)
            if (window.__additionalDataLoaded) {
                for (let key in window.__additionalDataLoaded) {
                    const data = window.__additionalDataLoaded[key];
                    if (data?.data?.user?.username) {
                        return data.data.user.username;
                    }
                }
            }

            return null;
        } catch (error) {
            console.error("Error extracting username:", error);
            return null;
        }
    };

    const navigateToProfile = () => {
        attempts++;
        console.log(`[${attempts}/${MAX_ATTEMPTS}] Attempting to find username...`);

        try {
            // Stop if max attempts reached
            if (attempts > MAX_ATTEMPTS) {
                console.warn("Max attempts reached, stopping...");
                clearInterval(intervalId);
                return;
            }

            const username = getUsername();

            if (username) {

                // Clear interval first
                clearInterval(intervalId);

                // Mark as navigated
                sessionStorage.setItem("ig_profile_navigated", "true");

                verifyProfile(username);
            } else {
                console.log("Username not found yet, retrying...");
            }
        } catch (error) {
            console.error("Error:", error);
        }
    };

    // Start attempting to navigate
    intervalId = setInterval(navigateToProfile, RETRY_INTERVAL);
    navigateToProfile(); // Run immediately
})();
